# POST /api/sheets/{sheetId}/today — set the sheet's today (body: {today: yyyy-MM-dd, user}).
# A date that does not parse is refused (400) and nothing is stored. A new today first records one
# SNAPSHOT line per person (their due-total on the day being left), preceded while the score log is on
# by one SCORE line per person (their score on that day), then only the ROLLUP/TOTALS lines
# of the figures it moved. With grace days set, every
# open period whose to-date plus the grace days is before the new today is then closed (by to-date) as a
# close by hand would, each recorded as PERIOD_CLOSED ... auto=yes before the ROLLUP/TOTALS lines.
validate:
  class: net.officefloor.hq.app.sheet.ValidateToday
  next: snapshot
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.sheet.SaveToday
  govern: [ transaction ]
  next: autoClose
autoClose:
  class: net.officefloor.hq.app.sheet.AutoClosePeriods
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.sheet.AuditToday
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.sheet.RespondWithSheet
  govern: [ transaction ]
# POST /api/sheets/{sheetId}/periods/{periodName}/close — close a period (body: {user}), fixing its
# due-total, each person's due-total and every pool member's cut in it as they are now (the figures of the claims that count due by a date in it, skipping n/a); later rate
# changes do not alter it. Refused (400) when the sheet's permission matrix (perm-close; by default a
# clerk or a steward) does not allow the user's role, when the period is not on the sheet or is already closed;
# nothing is stored then. A soft-closed period may be closed, fixing its figures afresh. A closed period is recorded in the audit file as PERIOD_CLOSED.
validate:
  class: net.officefloor.hq.app.period.ValidateClose
  next: close
close:
  class: net.officefloor.hq.app.period.ClosePeriod
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.period.AuditPeriodClosed
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithClosedPeriod
  govern: [ transaction ]
25: *  value). The policy date, the period numbering date, the entry date, the grace days, the escalation gap, the review SLA, the pot, the alert threshold, the parent sheet, the fiscal start month, the default grade, the proof kinds and the permission matrix are not dated. */
254:    /** The key of an action's permission: perm-open, perm-settle, and so on. */
255:    public static final String PERM_PREFIX = "perm-";
257:    /** The roles that may take each action while its permission is blank (the standing rule). */
263:    /** The actions of the permission matrix, in the order the screen shows them. */
327:     *  permission, else, when blank, the standing rule. A restricted user takes the actions a clerk may. */
340:    /** The permissions recorded, by action; a blank one is null (the standing rule). */
341:    public Map<String, String> perms(String sheetId) {
342:        Map<String, String> perms = new LinkedHashMap<>();
344:            perms.put(action, find(sheetId, PERM_PREFIX + action));
346:        return perms;
// The fiscal start month (1 to 12, not dated) is the month a fiscal year starts in; 1 unless set.
// The proof kinds (receipt, photo; comma separated, blank for none, not dated) are the kinds a claim above its proof
// threshold needs at least one proof of each of before it is settled or approved.
// The score log (on, blank for off, not dated) writes each person's score on the day being left to the audit file
// when the sheet's today moves.
// The maximum of open claims (a whole number, blank for none, not dated) is the most OPEN or PENDING claims a person
// may have for another of theirs to be opened.
function SheetSettings() {
  const fig = useFigure();
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const settings = useSettings(sheet);
  const [values, setValues] = useState<Record<Key, string>>({ 'clerk-limit': '', 'clerk-limit-A': '', 'clerk-limit-B': '', 'clerk-limit-C': '', floor: '', terms: '', 'terms-A': '', 'terms-B': '', 'terms-C': '', 'grace-A': '', 'grace-B': '', 'grace-C': '', 'late-pct': '', 'policy-date': '', 'period-numbering-from': '', cap: '', 'proof-threshold': '', 'proof-threshold-A': '', 'proof-threshold-B': '', 'proof-threshold-C': '', 'note-threshold': '', 'review-threshold': '', 'grace-days': '', 'escalate-after': '', 'review-sla': '', 'pending-sla': '', 'entry-date': '', pot: '', 'alert-threshold': '', parent: '', 'fiscal-start-month': '', rounding: '', 'proof-kinds': '', 'default-grade': '', 'score-mid': '', 'score-high': '', 'score-log': '', 'max-open': '',
    'perm-open': '', 'perm-settle': '', 'perm-void': '', 'perm-reassign': '', 'perm-close': '', 'perm-reopen': '' });
  const [froms, setFroms] = useState<Record<DatedKey, string>>(NO_FROM);
  const [key, setKey] = useState<Key>('clerk-limit');
  const queryClient = useQueryClient();

  const save = useMutation({
    mutationFn: ({ key, value, from }: { key: Key; value: string; from: string }) =>
      postJson<Settings>(`/api/sheets/${encodeURIComponent(sheet)}/settings`, { key, value, from, user }),
    onSuccess: async (_, { key }) => {
      await queryClient.invalidateQueries({ queryKey: settingsKey(sheet) });
      if (key === 'pot') await queryClient.invalidateQueries({ queryKey: poolsKey(sheet) });
      if (key === 'parent') await queryClient.invalidateQueries({ queryKey: ratesKey(sheet) });
      setValues((v) => ({ ...v, [key]: '' }));
      if (isDated(key)) setFroms((f) => ({ ...f, [key]: '' }));
    },
  });
  const submit = useSubmitOnce(save);

